type Analysis = { pattern: string; confidence: number; breakoutProbability: number; breakdownProbability: number; riskReward: number; averageReturn: number; recommendation: string };
type Workflow = { id: string; step: string; progress: number; symbol: string; timeframe: string; message: string };
type AlertItem = { id: string; symbol: string; type: string; condition: string; timeframe: string; channels: string[]; active: boolean; lastTriggered: string };
type AnalyticsOverview = { range: string; totalProfit: number; netProfit: number; grossProfit: number; grossLoss: number; winRate: number; lossRate: number; averageWin: number; averageLoss: number; profitFactor: number; sharpeRatio: number; sortinoRatio: number; maximumDrawdown: number; expectancy: number; aiPredictionAccuracy: number; patternSuccessRate: number; monthlyReturns: { label: string; value: number }[]; patternPerformance: { pattern: string; successRate: number; trades: number; averageReturn: number }[] };
type AnalyticsTrade = { id: string; symbol: string; side: string; pattern: string; closedOn: string; pnl: number; returnPercent: number; riskReward: number; outcome: string };
type SystemDashboard = { cpu: number; ram: number; gpu: number; disk: number; healthScore: number; memoryUsedGb: number; memoryTotalGb: number; diskIoMbps: number; networkMbps: number; database: string; broker: string; websocket: string; tradingView: string; scanner: string; ai: string; apiLatency: number; executionQueue: number; errorCount: number; services: { name: string; status: string; latencyMs: number }[] };
