function Metric({ label, value, color }: { label: string; value: string; color: 'green' | 'red' }) { return <div className="metric"><div><span>{label}</span><strong className={color === 'green' ? 'positive' : 'negative'}>{value}</strong></div><div className={`metric-bar ${color}`}><i /></div></div>; }

function WorkflowBar({ workflow, onAdvance }: { workflow: Workflow; onAdvance: () => void }) {
  const labels = ['Broker', 'Data', 'Select', 'Extract', 'Matches', 'Stats', 'Recommend', 'Paper trade'];
  return <section className="workflow-bar panel"><div className="workflow-head"><div><span className="viewer-label">LIVE ANALYSIS WORKFLOW</span><strong>{workflow.message}</strong></div><button className="primary-button" onClick={onAdvance}>{workflow.progress >= labels.length ? 'Restart flow' : 'Continue workflow'}</button></div><div className="workflow-steps">{labels.map((label, index) => <div className={index < workflow.progress ? 'complete' : index === workflow.progress - 1 ? 'current' : ''} key={label}><i>{index < workflow.progress ? '✓' : index + 1}</i><span>{label}</span></div>)}</div></section>;
}

