const fallbackSystemAlerts: SystemAlert[] = [{ id: 'alert-01', message: 'Broker latency elevated', level: 'warning', service: 'IBKR', time: '16:41:52' }, { id: 'alert-02', message: 'Execution queue within threshold', level: 'info', service: 'Execution Queue', time: '16:40:12' }];
const fallbackSystemLogs: SystemLog[] = [{ time: '16:42:08', level: 'INFO', service: 'API Gateway', message: 'Request latency within threshold' }, { time: '16:41:52', level: 'INFO', service: 'AI Engine', message: 'Model cache refreshed' }, { time: '16:40:12', level: 'WARN', service: 'Broker IBKR', message: 'Latency above regional threshold' }];
const fallbackSystemJobs: BackgroundJob[] = [{ id: 'job-2048', name: 'Pattern scan', status: 'running', progress: 68, detail: '2,847 symbols' }, { id: 'job-2047', name: 'Analytics aggregation', status: 'completed', progress: 100, detail: '18,492 trades' }, { id: 'job-2046', name: 'AI model sync', status: 'queued', progress: 0, detail: 'PatternNet v3.2' }];

function SystemMonitorViewer({ onBack }: { onBack: () => void }) {
  const [dashboard, setDashboard] = useState(fallbackSystem);
  const [timeline, setTimeline] = useState(fallbackSystemTimeline);
  const [alerts, setAlerts] = useState(fallbackSystemAlerts);
  const [logs, setLogs] = useState(fallbackSystemLogs);
  const [jobs, setJobs] = useState(fallbackSystemJobs);
  const [tab, setTab] = useState('System Logs');
  const [lastUpdated, setLastUpdated] = useState('16:42:08');

  const refresh = () => {
    Promise.all([
      getJson<SystemDashboard>(`${API}/system/dashboard`, fallbackSystem),
      getJson<SystemMetric[]>(`${API}/system/timeline`, fallbackSystemTimeline),
      getJson<SystemAlert[]>(`${API}/system/alerts`, fallbackSystemAlerts),
      getJson<SystemLog[]>(`${API}/system/logs`, fallbackSystemLogs),
      getJson<BackgroundJob[]>(`${API}/system/jobs`, fallbackSystemJobs),
    ]).then(([nextDashboard, nextTimeline, nextAlerts, nextLogs, nextJobs]) => { setDashboard(nextDashboard); setTimeline(nextTimeline); setAlerts(nextAlerts); setLogs(nextLogs); setJobs(nextJobs); setLastUpdated(new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })); });
  };

  useEffect(() => { refresh(); const timer = window.setInterval(refresh, 15000); return () => window.clearInterval(timer); }, []);
  const healthTone = dashboard.healthScore >= 90 ? 'healthy' : dashboard.healthScore >= 70 ? 'warning' : 'critical';
  const resources = [{ label: 'CPU', value: dashboard.cpu, detail: `${dashboard.cpu}%` }, { label: 'RAM', value: dashboard.ram, detail: `${dashboard.memoryUsedGb} / ${dashboard.memoryTotalGb} GB` }, { label: 'GPU', value: dashboard.gpu, detail: `${dashboard.gpu}%` }, { label: 'Disk I/O', value: dashboard.disk, detail: `${dashboard.diskIoMbps} MB/s` }];
  const connections = [['Database', dashboard.database], ['Broker API', dashboard.broker], ['WebSocket', dashboard.websocket], ['TradingView', dashboard.tradingView], ['Scanner', dashboard.scanner], ['AI Engine', dashboard.ai]];
  return <div className="app-shell system-shell"><header className="topbar"><div className="brand"><div className="brand-mark"><Sparkles size={15} /></div><span>AI Pattern Analyzer <b>Pro</b></span></div><div className="system-title"><span className="divider" /><strong>System Monitoring &amp; Infrastructure Dashboard</strong><span className={`system-health ${healthTone}`}>● All systems operational</span></div><div className="top-actions"><button className="secondary-button" onClick={refresh}><RefreshCw size={13} /> Refresh</button><button className="secondary-button" onClick={onBack}><ArrowLeft size={13} /> Terminal</button><button className="avatar">DT</button></div></header><main className="system-body"><aside className="system-resources panel"><div className="viewer-label">SYSTEM RESOURCES</div>{resources.map(resource => <div className="resource-card" key={resource.label}><div><span>{resource.label}</span><strong>{resource.detail}</strong></div><div className="resource-bar"><i className={resource.value > 70 ? 'warning' : ''} style={{ width: `${resource.value}%` }} /></div></div>)}<div className="viewer-label system-section-label">SERVICE HEALTH</div>{dashboard.services.map(service => <div className="service-row" key={service.name}><span><i className={service.status === 'healthy' ? 'ok' : 'warn'} />{service.name}</span><strong>{service.latencyMs}ms</strong></div>)}</aside><section className="system-center"><div className="system-kpis">{[['Health score', `${dashboard.healthScore}%`, 'positive'], ['API latency', `${dashboard.apiLatency}ms`, 'blue-text'], ['Execution queue', `${dashboard.executionQueue}`, 'blue-text'], ['Open errors', `${dashboard.errorCount}`, dashboard.errorCount > 0 ? 'warning-text' : 'positive']].map(([label, value, tone]) => <div className="system-kpi panel" key={label}><span>{label}</span><strong className={tone}>{value}</strong><small>{label === 'Health score' ? 'Platform health' : 'Current reading'}</small></div>)}</div><section className="panel system-chart-panel"><div className="panel-header"><strong><Activity size={15} /> Performance timeline</strong><span className="status-tag">LIVE · {lastUpdated}</span></div><div className="system-chart"><div className="system-chart-grid" />{timeline.map((point, index) => <div className="system-point" key={point.time} style={{ left: `${index / Math.max(1, timeline.length - 1) * 100}%`, bottom: `${Math.min(92, point.gpu)}%` }}><i /><span>{point.gpu}%</span></div>)}<div className="system-chart-labels">{timeline.map(point => <span key={point.time}>{point.time}</span>)}</div></div><div className="system-legend"><span><i className="legend-blue" /> GPU utilization</span><span><i className="legend-green" /> API latency {dashboard.apiLatency}ms</span><span className="status-spacer" />Network {dashboard.networkMbps} Mbps</div></section><section className="panel connection-panel"><div className="panel-header"><strong><Wifi size={15} /> Platform connections</strong><span className="muted">6 monitored services</span></div><div className="connection-grid">{connections.map(([name, status]) => <div className="connection-card" key={name}><i className={status === 'connected' || status === 'synced' || status === 'ready' || status === 'running' ? 'ok' : 'warn'} /><div><strong>{name}</strong><span>{status}</span></div><b>{status === 'connected' || status === 'synced' || status === 'ready' || status === 'running' ? 'ONLINE' : 'CHECK'}</b></div>)}</div></section></section><aside className="system-side panel"><div className="panel-header"><strong><Bell size={15} /> Alerts</strong><span className="status-tag">{alerts.length} ACTIVE</span></div>{alerts.map(alert => <div className="system-alert" key={alert.id}><i className={alert.level === 'warning' ? 'warn' : 'ok'} /><div><strong>{alert.message}</strong><span>{alert.service} · {alert.time}</span></div></div>)}<div className="panel-header system-side-heading"><strong><Activity size={15} /> Background jobs</strong></div>{jobs.map(job => <div className="system-job" key={job.id}><div><strong>{job.name}</strong><span>{job.detail} · {job.status}</span></div><b>{job.progress}%</b><div className="resource-bar"><i style={{ width: `${job.progress}%` }} /></div></div>)}</aside></main><section className="system-bottom panel"><div className="viewer-tabs">{['System Logs', 'Warnings', 'Errors', 'Background Jobs', 'Performance History'].map(item => <button key={item} className={tab === item ? 'active' : ''} onClick={() => setTab(item)}>{item}</button>)}</div><div className="system-bottom-content">{tab === 'Background Jobs' ? jobs.map(job => <div className="system-bottom-row" key={job.id}><b>{job.name}</b><span>{job.status}</span><span>{job.detail}</span><strong>{job.progress}%</strong></div>) : tab === 'Performance History' ? <div className="history-bars">{timeline.map(point => <i key={point.time} style={{ height: `${point.gpu}%` }} title={`${point.time}: ${point.gpu}% GPU`} />)}</div> : logs.filter(log => tab === 'System Logs' || (tab === 'Warnings' ? log.level === 'WARN' : tab === 'Errors' ? log.level === 'ERROR' : true)).map(log => <div className="system-bottom-row" key={`${log.time}-${log.message}`}><b>{log.time}</b><span className={log.level === 'WARN' ? 'warning-text' : 'positive'}>{log.level}</span><span>{log.service} · {log.message}</span></div>)}</div><footer className="statusbar"><span><i className="status-dot" /> System nominal</span><span><Gauge size={13} /> CPU {dashboard.cpu}%</span><span><Database size={13} /> Database {dashboard.database}</span><span><Bot size={13} /> AI {dashboard.ai}</span><span className="status-spacer" /><span>Updated {lastUpdated}</span></footer></section></div>;
}

