type ReplayState = { id: string; symbol: string; timeframe: string; candle: number; totalCandles: number; phase: string; probability: number; breakoutProbability: number; breakdownProbability: number; pattern: string };
type ReplayTrade = { id: string; side: string; candle: number; entry: number; current: number; returnPercent: number; status: string; createdAt?: string };
type ReplayReview = { sessionId: string; decisionScore: number; trades: number; riskReward: number; breakoutProbability: number; breakdownProbability: number; suggestions: string[] };
const fallbackReplay: ReplayState = { id: 'local-replay', symbol: 'BTC/USDT', timeframe: '4H', candle: 1, totalCandles: 60, phase: 'Pre-Pattern', probability: 74, breakoutProbability: 72, breakdownProbability: 28, pattern: 'Bull Flag' };
const fallbackReplayReview: ReplayReview = { sessionId: 'local-replay', decisionScore: 78, trades: 0, riskReward: 2.6, breakoutProbability: 72, breakdownProbability: 28, suggestions: ['Wait for volume confirmation before breakout entries', 'Risk was within the configured 2% limit'] };

function ReplayViewer({ onBack }: { onBack: () => void }) {
  const [state, setState] = useState<ReplayState>(fallbackReplay);
  const [playing, setPlaying] = useState(false);
  const [speed, setSpeed] = useState(1);
  const [tab, setTab] = useState('Replay Timeline');
  const [events, setEvents] = useState<{ candle: number; message: string; type: string }[]>([]); const [trades, setTrades] = useState<ReplayTrade[]>([]); const [review, setReview] = useState<ReplayReview>(fallbackReplayReview); const [mode, setMode] = useState('Manual Mode');
  useEffect(() => { postJson<ReplayState>(`${API}/replay/sessions`, { symbol: state.symbol, timeframe: state.timeframe, date: '2026-01-15' }, fallbackReplay).then(setState); getJson(`${API}/replay/sessions/local-replay/events`, [],).then(setEvents); }, []);
  useEffect(() => { if (!playing) return; const timer = window.setInterval(() => { setState(current => { const next = Math.min(current.totalCandles, current.candle + 1); if (next >= current.totalCandles) setPlaying(false); return { ...current, candle: next, phase: next < 15 ? 'Pre-Pattern' : next < 28 ? 'Formation' : next < 42 ? 'Consolidation' : next < 45 ? 'Breakout' : 'Post-Breakout' }; }); }, Math.max(80, 500 / speed)); return () => window.clearInterval(timer); }, [playing, speed]);
  const step = (amount: number) => postJson<ReplayState>(`${API}/replay/sessions/${state.id}/step`, { symbol: state.symbol, timeframe: state.timeframe, candle: state.candle + amount }, { ...state, candle: Math.max(1, Math.min(state.totalCandles, state.candle + amount)) }).then(setState);
  const executeTrade = async (side: string) => { const trade = await postJson<ReplayTrade>(`${API}/replay/sessions/${state.id}/trades`, { side, candle: state.candle }, { id: `local-trade-${Date.now()}`, side, candle: state.candle, entry: 43280, current: 44100, returnPercent: 3, status: 'Open' }); setTrades(current => [...current, trade]); const nextReview = await getJson<ReplayReview>(`${API}/replay/sessions/${state.id}/review`, { ...review, trades: trades.length + 1 }); setReview(nextReview); setTab('Trade Log'); };
  const percent = Math.round(state.candle / state.totalCandles * 100);
  return <div className="app-shell replay-shell"><header className="topbar"><div className="brand"><div className="brand-mark"><Sparkles size={15} /></div><span>AI Pattern Analyzer <b>Pro</b></span></div><div className="replay-title"><span className="divider" /><strong>Replay &amp; Pattern Outcome Simulator</strong><select value={state.symbol} onChange={event => setState({ ...state, symbol: event.target.value })}>{symbols.slice(0, 4).map(item => <option key={item}>{item}</option>)}</select><select value={state.timeframe} onChange={event => setState({ ...state, timeframe: event.target.value })}>{['1H', '4H', '1D'].map(item => <option key={item}>{item}</option>)}</select><input type="date" defaultValue="2026-01-15" /></div><div className="top-actions"><button className="secondary-button" onClick={() => step(-1)}>Prev</button><button className="primary-button" onClick={() => setPlaying(!playing)}>{playing ? 'Pause' : 'Play'}</button><button className="secondary-button" onClick={() => step(1)}>Next</button><select value={speed} onChange={event => setSpeed(Number(event.target.value))}><option value={1}>1x</option><option value={2}>2x</option><option value={5}>5x</option><option value={10}>10x</option></select><button className="avatar">DT</button></div></header><div className="replay-body"><aside className="replay-controls panel"><div className="viewer-label">REPLAY CONTROLS</div><div className="replay-card"><DetailRow label="Current candle" value={`${state.candle} / ${state.totalCandles}`} /><DetailRow label="Pattern" value={state.pattern} tone="blue-text" /><DetailRow label="Phase" value={state.phase} /><DetailRow label="Confidence" value="87%" tone="positive" /></div><div className="viewer-label">PATTERN ZONE</div><div className="replay-card"><DetailRow label="Start" value="Candle 15" /><DetailRow label="Peak" value="Candle 28" /><DetailRow label="End" value="Candle 42" /><DetailRow label="Breakout" value="Candle 44" tone="positive" /></div><button className="secondary-button replay-control-button" onClick={() => setState({ ...state, candle: 44 })}>Jump to breakout</button><button className="secondary-button replay-control-button" onClick={() => setState({ ...state, candle: 52 })}>Jump to target</button><button className="secondary-button replay-control-button" onClick={() => { setState({ ...state, candle: 1 }); setPlaying(false); }}>Reset replay</button></aside><main className="replay-main panel"><div className="replay-chart-head"><div><strong>{state.symbol}</strong><span>{state.timeframe} · {state.pattern} · Historical replay</span></div><span className="positive">+2.4%</span></div><div className="replay-canvas"><MiniChart selected /><div className="replay-candle-marker" style={{ left: `${percent}%` }} /><div className="replay-price">$43,280</div><div className="replay-chart-indicators"><span>EMA aligned</span><span>VWAP</span><span>RSI 64</span><span>MACD +</span><span>ATR 2.1%</span></div></div><div className="replay-scrubber"><span>0%</span><input type="range" min="1" max={state.totalCandles} value={state.candle} onChange={event => step(Number(event.target.value) - state.candle)} /><span>{percent}%</span></div></main><aside className="replay-ai panel"><div className="panel-header"><strong><Bot size={15} /> AI Outcome Prediction</strong><span className="status-tag">LIVE</span></div><div className="replay-probability"><span>Probability</span><strong>{state.probability}%</strong><b>BULLISH</b></div><div className="replay-card"><DetailRow label="Breakout" value={`${state.breakoutProbability}%`} tone="positive" /><DetailRow label="Breakdown" value={`${state.breakdownProbability}%`} tone="negative" /><DetailRow label="Target 1" value="+4.2%" tone="positive" /><DetailRow label="Target 2" value="+8.6%" tone="positive" /><DetailRow label="Stop" value="-2.1%" tone="negative" /><DetailRow label="Risk / reward" value="1:2.0" /><DetailRow label="Pattern win rate" value="72.3%" /></div><div className="ai-note"><Bot size={17} /><div><strong>AI Insight</strong><p>{state.phase === 'Post-Breakout' ? 'Breakout confirmed. Historical target zone is now active.' : 'Bull Flag with strong pole. Volume confirmation is needed before breakout.'}</p></div></div><button className="primary-button replay-trade">Prepare paper trade</button></aside></div><section className="replay-bottom panel"><div className="viewer-tabs">{['Candle Details', 'Pattern Stats', 'Evolution', 'AI Notes', 'Replay Events'].map(item => <button key={item} className={tab === item ? 'active' : ''} onClick={() => setTab(item)}>{item}</button>)}</div><div className="replay-bottom-content">{tab === 'Candle Details' && <div className="notes"><strong>Candle {state.candle} · {state.phase}</strong><span>Open $43,120 · High $43,410 · Low $42,980 · Close $43,280 · Volume 1.28M</span></div>}{tab === 'Pattern Stats' && <div className="replay-stats"><DetailRow label="Average return" value="+5.2%" tone="positive" /><DetailRow label="Breakout probability" value="72%" tone="positive" /><DetailRow label="Average duration" value="18 candles" /><DetailRow label="Risk score" value="28 / 100" /></div>}{tab === 'Evolution' && <div className="replay-evolution">{Array.from({ length: 36 }, (_, index) => <i key={index} className={index < state.candle / 2 ? 'seen' : ''} style={{ height: `${24 + ((index * 17) % 65)}%` }} />)}</div>}{tab === 'AI Notes' && <div className="notes"><strong>Replay interpretation</strong><span>The pattern formed through consolidation before a confirmed breakout. The simulator keeps future candles hidden until playback reaches them.</span></div>}{tab === 'Replay Events' && <div className="log-lines">{events.map(event => <span key={`${event.candle}-${event.message}`}><b>Candle {event.candle}</b> {event.message} · <em>{event.type}</em></span>)}</div>}</div></section><footer className="statusbar"><span><i className="status-dot" /> Replay session active</span><span><Bot size={13} /> AI prediction live</span><span className="status-spacer" /><span>{state.candle} / {state.totalCandles} candles · {speed}x</span><span>16:42:08 UTC</span></footer></div>;
}

