function ScannerViewer({ onBack }: { onBack: () => void }) {
  const [running, setRunning] = useState(true);
  const [minConfidence, setMinConfidence] = useState(72);
  const [minSimilarity, setMinSimilarity] = useState(75);
  const [query, setQuery] = useState('');
  const [market, setMarket] = useState('All markets');
  const [tab, setTab] = useState('Scanner Logs');
  const [selectedId, setSelectedId] = useState(1);
  const [tick, setTick] = useState(0);
  useEffect(() => { if (!running) return; const timer = window.setInterval(() => setTick(value => value + 1), 2200); return () => window.clearInterval(timer); }, [running]);
  const results = scanSeeds.map((result, index) => ({ ...result, confidence: Math.min(99, result.confidence + ((tick + index) % 3)), change: +(result.change + Math.sin((tick + index) / 3) * .2).toFixed(2) })).filter(result => result.confidence >= minConfidence && result.similarity >= minSimilarity && `${result.symbol} ${result.pattern}`.toLowerCase().includes(query.toLowerCase())).filter(result => market === 'All markets' || (market === 'Crypto' ? result.symbol.includes('/') : !result.symbol.includes('/')));
  const selected = results.find(result => result.id === selectedId) ?? results[0] ?? scanSeeds[0];
  const top = [...results].sort((a, b) => b.confidence - a.confidence).slice(0, 3);

  return <div className="app-shell scanner-shell"><header className="topbar"><div className="brand"><div className="brand-mark"><Sparkles size={15} /></div><span>AI Pattern Analyzer <b>Pro</b></span></div><div className="scanner-title"><span className="divider" /><strong>AI Pattern Scanner</strong><select><option>All brokers</option><option>Alpaca</option><option>Binance</option><option>IBKR</option></select><select value={market} onChange={event => setMarket(event.target.value)}><option>All markets</option><option>Crypto</option><option>Equities</option></select><select><option>All symbols</option><option>Watchlist</option><option>Top 50</option></select><select><option>All timeframes</option><option>15M</option><option>4H</option><option>1D</option></select></div><div className="top-actions"><button className="secondary-button" onClick={() => setRunning(!running)}>{running ? <Pause size={13} /> : <Play size={13} />} {running ? 'Pause' : 'Resume'}</button><button className="icon-button" title="Export scan"><Download size={14} /></button><button className="avatar">DT</button></div></header><div className="scanner-body"><aside className="scanner-controls panel"><div className="viewer-label">SCANNER CONTROLS</div><ControlSelect label="Broker" value="All brokers" options={['All brokers', 'Alpaca', 'Binance', 'IBKR']} /><div className="control-section"><span className="control-label">Market type</span>{['Crypto', 'Equities', 'Forex', 'Futures', 'Indices'].map(item => <label key={item}><input type="checkbox" defaultChecked={item === 'Crypto' || item === 'Equities'} /> {item}</label>)}</div><div className="control-section"><span className="control-label">Pattern type</span>{['Flag & Pennant', 'Triangle', 'Double Top / Bottom', 'Head & Shoulders', 'Wedge'].map(item => <label key={item}><input type="checkbox" defaultChecked /> {item}</label>)}</div><RangeControl label="Minimum confidence" value={minConfidence} min={50} max={99} onChange={setMinConfidence} /><RangeControl label="Minimum similarity" value={minSimilarity} min={60} max={99} onChange={setMinSimilarity} /><button className="primary-button scanner-run" onClick={() => { setRunning(true); setTick(value => value + 1); }}><Play size={14} /> Run scanner</button><button className="secondary-button scanner-reset" onClick={() => { setMinConfidence(72); setMinSimilarity(75); setQuery(''); setMarket('All markets'); }}>Reset filters</button><div className="scan-counters"><div><span>Symbols scanned</span><strong>2,847</strong></div><div><span>Patterns found</span><strong>{results.length}</strong></div><div><span>High priority</span><strong className="negative">{results.filter(item => item.confidence >= 90).length}</strong></div><div><span>Scan speed</span><strong>847/s</strong></div></div></aside><section className="scanner-results panel"><div className="scanner-results-head"><div><strong>Live Scan Results</strong><span className="muted"> · {running ? 'Scanning markets...' : 'Scan paused'} · updated {tick + 1}s ago</span></div><div className="result-tools"><label className="viewer-search"><Search size={13} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Filter results..." /></label><button className="icon-button" title="Filter results"><Filter size={14} /></button><span className="muted">{results.length} results</span></div></div><div className="scan-table-wrap"><table className="scan-table"><thead><tr><th>Symbol</th><th>Broker</th><th>Pattern</th><th>TF</th><th>Change</th><th>Confidence</th><th>Similarity</th><th>Signal</th><th>Volume</th></tr></thead><tbody>{results.map(result => <tr key={result.id} className={selected?.id === result.id ? 'selected-row' : ''} onClick={() => setSelectedId(result.id)}><td><strong>{result.symbol}</strong>{result.id === 1 && <em>NEW</em>}</td><td>{result.broker}</td><td>{result.pattern}</td><td>{result.timeframe}</td><td className={result.change >= 0 ? 'positive' : 'negative'}>{result.change >= 0 ? '+' : ''}{result.change}%</td><td><span className="table-confidence"><i style={{ width: `${result.confidence}%` }} />{result.confidence}%</span></td><td className="positive">{result.similarity}%</td><td><span className={`signal-pill ${result.signal.toLowerCase()}`}>{result.signal}</span></td><td className={result.volume === 'High' ? 'warning-text' : ''}>{result.volume}</td></tr>)}</tbody></table></div></section><aside className="scanner-opportunities panel"><div className="panel-header"><strong><Bot size={15} /> Top Opportunities</strong><span className="status-tag">LIVE</span></div>{top.map(result => <button className="opportunity" key={result.id} onClick={() => setSelectedId(result.id)}><div><strong>{result.symbol}</strong><span className={`signal-pill ${result.signal.toLowerCase()}`}>{result.signal}</span></div><span>{result.pattern} · {result.timeframe}</span><div><small>Confidence</small><b>{result.confidence}%</b></div><div><small>Similarity</small><b className="positive">{result.similarity}%</b></div></button>)}<div className="scanner-pulse"><Bot size={16} /><div><strong>AI Market Pulse</strong><p>{selected.symbol} {selected.pattern} detected with {selected.confidence}% confidence. {selected.signal === 'LONG' ? 'Momentum favors continuation.' : 'Wait for confirmation before acting.'}</p></div></div></aside></div><section className="scanner-bottom panel"><div className="viewer-tabs">{['Scanner Logs', 'Alerts', 'Preview', 'Queue', 'History'].map(item => <button key={item} className={tab === item ? 'active' : ''} onClick={() => setTab(item)}>{item}</button>)}</div><div className="scanner-bottom-content">{tab === 'Scanner Logs' && <div className="log-lines"><span><b>16:42:08</b> Scanner cycle completed · 2,847 symbols checked · {results.length} signals ranked</span><span><b>16:42:06</b> {selected.symbol} {selected.pattern} detected · {selected.confidence}% confidence</span></div>}{tab === 'Alerts' && <div className="notes"><strong>{results.filter(item => item.confidence >= 85).length} high-priority alerts</strong><span>Signals above the confidence threshold are ready for historical review.</span></div>}{tab === 'Preview' && <div className="bottom-preview"><MiniChart selected /><div><strong>{selected.symbol} · {selected.pattern}</strong><p>Signal {selected.signal} · {selected.confidence}% confidence · {selected.similarity}% similarity</p></div></div>}{tab === 'Queue' && <div className="notes"><strong>Deep analysis queue</strong><span>{results.map(item => item.symbol).join(' · ')}</span></div>}{tab === 'History' && <div className="notes"><strong>Today's scan history</strong><span>12 completed cycles · 847 symbols per second · highest confidence {Math.max(...scanSeeds.map(item => item.confidence))}%</span></div>}</div></section><footer className="statusbar"><span><i className="status-dot" /> Scanner {running ? 'running' : 'paused'}</span><span><Bot size={13} /> AI engine ready</span><span className="status-spacer" /><span>2,847 symbols · {results.length} matches</span><span>16:42:08 UTC</span></footer></div>;
}

